// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Montserrat');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily } = loadFont();



export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#0e1013",
  transparentBackground = false,
  durationInSeconds = 8,
  blueColor = "#4196E2",
  redColor = "#DE4343",
  titleHigh = "EXTREME HIGH",
  titleLow = "EXTREME LOW",
  barGap = 4,
  staggerSpeed = 0.5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color security logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Key timings scaled to duration
  const totalFrames = durationInSeconds * fps;
  const startBlueFrame = totalFrames * 0.1;
  const peakBlueFrame = totalFrames * 0.35;
  const switchStartFrame = totalFrames * 0.55;
  const switchEndFrame = totalFrames * 0.8;

  // Stagger helper for Blue Growth & Shrink
  const getBarProgressBlue = (index: number) => {
    const delay = index * staggerSpeed;
    const t1 = startBlueFrame + delay;
    const t2 = peakBlueFrame + delay;
    const t3 = switchStartFrame + delay;
    const t4 = switchEndFrame + delay;
    return interpolate(
      frame,
      [0, t1, t2, t3, t4],
      [0, 0, 1, 1, 0],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }
    );
  };

  // Stagger helper for Red Growth
  const getBarProgressRed = (index: number) => {
    const delay = index * staggerSpeed;
    const t3 = switchStartFrame + delay;
    const t4 = switchEndFrame + delay;
    return interpolate(
      frame,
      [0, t3, t4],
      [0, 0, 1],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }
    );
  };

  // Global Fade In at launch
  const globalOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Chart layout proportions
  const containerPadding = width * 0.06;
  const contentWidth = width - containerPadding * 2;
  const chartHeight = height * 0.52;
  const labelMarginTop = height * 0.05;
  const axisThickness = Math.min(width, height) * 0.003;
  const barBorderRadius = Math.min(width, height) * 0.0025;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        padding: `${containerPadding}px`,
        opacity: globalOpacity,
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          width: `${contentWidth}px`,
          transition: "none",
        }}
      >
        {/* SINGLE GRAPH CONTAINER */}
        <div
          style={{
            position: "relative",
            width: "100%",
            height: `${chartHeight}px`,
            borderBottom: `${axisThickness}px solid rgba(255, 255, 255, 0.15)`,
            display: "flex",
            flexDirection: "row",
            alignItems: "flex-end",
            justifyContent: "space-between",
            transition: "none",
          }}
        >
          {/* Left Section (Blue bars) */}
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              alignItems: "flex-end",
              width: "46%",
              height: "100%",
              gap: `${barGap}px`,
              transition: "none",
            }}
          >
            {Array.from({ length: 20 }).map((_, index) => {
              const targetHeight = 0.1 + 0.9 * (index / 19);
              const currentProgress = getBarProgressBlue(index);
              const heightPercentage = interpolate(
                currentProgress,
                [0, 1],
                [2, targetHeight * 100],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );

              return (
                <div
                  key={`blue-bar-${index}`}
                  style={{
                    flex: 1,
                    height: `${heightPercentage}%`,
                    backgroundColor: blueColor,
                    borderTopLeftRadius: `${barBorderRadius}px`,
                    borderTopRightRadius: `${barBorderRadius}px`,
                    transition: "none",
                  }}
                />
              );
            })}
          </div>

          {/* Separator Spacer */}
          <div style={{ width: "8%", height: "100%", transition: "none" }} />

          {/* Right Section (Red bars) */}
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              alignItems: "flex-end",
              width: "46%",
              height: "100%",
              gap: `${barGap}px`,
              transition: "none",
            }}
          >
            {Array.from({ length: 20 }).map((_, index) => {
              const targetHeight = 0.1 + 0.9 * (index / 19);
              const currentProgress = getBarProgressRed(index);
              const heightPercentage = interpolate(
                currentProgress,
                [0, 1],
                [2, targetHeight * 100],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );

              return (
                <div
                  key={`red-bar-${index}`}
                  style={{
                    flex: 1,
                    height: `${heightPercentage}%`,
                    backgroundColor: redColor,
                    borderTopLeftRadius: `${barBorderRadius}px`,
                    borderTopRightRadius: `${barBorderRadius}px`,
                    transition: "none",
                  }}
                />
              );
            })}
          </div>
        </div>

        {/* LABELS ROW BELOW GRAPH */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            width: "100%",
            marginTop: `${labelMarginTop}px`,
            transition: "none",
          }}
        >
          {/* Left Label */}
          <div
            style={{
              color: blueColor,
              fontSize: `${width * 0.026}px`,
              fontWeight: 800,
              letterSpacing: "0.08em",
              width: "46%",
              textAlign: "center",
              transition: "none",
            }}
          >
            {titleHigh}
          </div>

          {/* Spacer */}
          <div style={{ width: "8%", transition: "none" }} />

          {/* Right Label */}
          <div
            style={{
              color: redColor,
              fontSize: `${width * 0.026}px`,
              fontWeight: 800,
              letterSpacing: "0.08em",
              width: "46%",
              textAlign: "center",
              transition: "none",
            }}
          >
            {titleLow}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;